CREATE TABLE customers (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    metadata JSONB
);

INSERT INTO customers (name, metadata) VALUES
    ('Amara Chen', '{"address": {"city": "Austin", "zip": "78701"}, "vip": true}');

SELECT
    metadata -> 'address' AS address_json,        -- {"city": "Austin", "zip": "78701"}  (jsonb)
    metadata -> 'address' ->> 'city' AS city,      -- Austin                                (text)
    metadata #>> '{address,zip}' AS zip,           -- 78701                                 (text)
    metadata ->> 'vip' AS vip_as_text               -- true                                  (text, NOT boolean!)
FROM customers;

-- Before any index: containment queries force a full scan.
EXPLAIN SELECT * FROM events WHERE payload @> '{"type": "click"}'::jsonb;
-- Seq Scan on events
--   Filter: (payload @> '{"type": "click"}'::jsonb)

CREATE INDEX idx_events_payload ON events USING GIN (payload);

EXPLAIN SELECT * FROM events WHERE payload @> '{"type": "click"}'::jsonb;
-- Bitmap Heap Scan on events
--   Recheck Cond: (payload @> '{"type": "click"}'::jsonb)
--   ->  Bitmap Index Scan on idx_events_payload
--         Index Cond: (payload @> '{"type": "click"}'::jsonb)

