SELECT to_tsvector('english', 'PostgreSQL indexes speed up searching and querying');
--  'index':2 'postgresql':1 'queri':7 'search':5 'speed':3 'up':4
-- (note: stop words 'and' removed; 'querying' stemmed to 'queri')

SELECT plainto_tsquery('english', 'searching for queries');
-- 'search' & 'queri'

SELECT title FROM articles
WHERE to_tsvector('english', body) @@ plainto_tsquery('english', 'searching for queries');
-- matches any article whose body contains both a form of 'search'
-- AND a form of 'query' -- 'for' is a stop word and contributes nothing

CREATE TABLE articles (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    search_vector TSVECTOR GENERATED ALWAYS AS (
        setweight(to_tsvector('english', title), 'A') ||
        setweight(to_tsvector('english', body), 'B')
    ) STORED
);

CREATE INDEX idx_articles_search ON articles USING GIN (search_vector);

SELECT id, title, ts_rank(search_vector, query) AS rank
FROM articles, to_tsquery('english', 'fox') AS query
WHERE search_vector @@ query
ORDER BY rank DESC
LIMIT 5;

