CREATE EXTENSION pg_trgm;

SELECT similarity('iphone', 'ihpone');    -- ~0.55, a plausible typo
SELECT similarity('iphone', 'android');  -- ~0.0,  genuinely different words

SELECT name FROM products WHERE name % 'ihpone';
-- matches 'iPhone' via the % similarity operator, even though
-- 'ihpone' is not a substring, prefix, or exact match of 'iPhone' at all

-- Before: a leading-wildcard ILIKE forces a full scan, regardless of
-- any ordinary B-tree index on name.
EXPLAIN SELECT * FROM products WHERE name ILIKE '%phone%';
-- Seq Scan on products
--   Filter: (name ~~* '%phone%'::text)

CREATE EXTENSION pg_trgm;
CREATE INDEX idx_products_name_trgm ON products USING GIN (name gin_trgm_ops);

EXPLAIN SELECT * FROM products WHERE name ILIKE '%phone%';
-- Bitmap Heap Scan on products
--   Recheck Cond: (name ~~* '%phone%'::text)
--   ->  Bitmap Index Scan on idx_products_name_trgm
--         Index Cond: (name ~~* '%phone%'::text)

-- Older pattern, requiring the extension:
CREATE EXTENSION "uuid-ossp";
CREATE TABLE sessions_v1 (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4()
);

-- Modern PostgreSQL (13+): no extension needed for the same result.
CREATE TABLE sessions_v2 (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid()
);

-- Contrast the resulting insertion pattern conceptually:
-- BIGINT IDENTITY inserts:  ...998, 999, 1000, 1001, 1002...
--   -- always appends at the END of the primary key's B-tree index.
-- Random UUID (v4) inserts: 3f2a91e2..., 08b7c410..., a91fd002...
--   -- each new value lands at an unpredictable, scattered position
--   -- throughout the ENTIRE index, not at any consistent edge.

exercises.solutionCode:
CREATE EXTENSION pg_trgm;

CREATE INDEX idx_products_name_trgm ON products USING GIN (name gin_trgm_ops);

SELECT name, similarity(name, 'wireles keybord') AS score
FROM products
WHERE name % 'wireles keybord'
ORDER BY score DESC;

